      R15 = DM(4, I2);
      R14 = LSHIFT R15 BY 13;
      R13 = R15 AND R14;
      R15 = R15 OR R14;
      R15 = R15 - R13;
      R14 = LSHIFT R15 BY -17;
      R13 = R15 AND R14;
      R15 = R15 OR R14;
      R15 = R15 - R13;
      R14 = LSHIFT R15 BY 5;
      R13 = R15 AND R14;
      R15 = R15 OR R14;
      R15 = R15 - R13;
      DM(4, I2) = R15;
      R12 = -0x1f;
      F15 = FLOAT R15 BY R12;
      F0 = PASS F15;
      JUMP (M14, I12);
.wr_fsc..end:
      .type wr_fsc.,STT_FUNC;
